// Writes docs/script.md from the shared script module, so the reviewed script, the film and the
// website transcript cannot drift apart. Run with `pnpm docs`.
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { formatTimestamp, overviewChapters, overviewFilm, plainText } from "../../src/lib/project-overview.ts";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const name = "{name}";
const lines: string[] = [
  "# Project-overview film — script",
  "",
  "<!-- Generated by `pnpm docs` from web/src/lib/project-overview.ts. Edit the module, not this file. -->",
  "",
  `Duration ${formatTimestamp(overviewFilm.durationSeconds)} (${overviewFilm.durationSeconds} s) · ${overviewFilm.width} × ${overviewFilm.height} · ${overviewFilm.fps} fps · instrumental soundtrack at ${overviewFilm.bpm} BPM, no voiceover. \`{name}\` is the configurable project name. *Italics* mark Instrument Serif emphasis. Claim IDs refer to [claims.md](claims.md).`,
  "",
];
for (const chapter of overviewChapters) {
  lines.push(`## ${chapter.number} · ${chapter.title} — ${formatTimestamp(chapter.start)}–${formatTimestamp(chapter.end)} (${chapter.end - chapter.start} s, ${chapter.theme})`, "");
  lines.push("| Time | On-screen narrative | Labels and visuals | Claims |", "| --- | --- | --- | --- |");
  chapter.beats.forEach((beat, index) => {
    const end = chapter.beats[index + 1]?.at ?? chapter.end;
    const narrative = [beat.heading ? `**${plainText(beat.heading, name)}**` : "", beat.text.replaceAll("*", "_"), ...(beat.items ?? []).map(item => `• ${item}`)].filter(Boolean).join("<br>");
    const visual = [beat.visual ?? "", beat.table ? `Table: ${beat.table.rows.map(row => row.join(" | ")).join("; ")}. ${beat.table.note}` : ""].filter(Boolean).join(" ").replaceAll("|", "\\|");
    lines.push(`| ${beat.at.toFixed(1)}–${end.toFixed(1)} s | ${narrative.replaceAll("|", "\\|")} | ${visual} | ${beat.claims.join(", ") || "—"} |`);
  });
  lines.push("");
}
writeFileSync(join(root, "docs", "script.md"), lines.join("\n"));
console.log("docs/script.md written");
